import recall
import api


def test_same_day():
    assert 2 in [m["id"] for m in recall.recall("2026-11-01")]


def test_future_empty():
    assert recall.recall("2030-01-01") == []


def test_impossible_date():
    assert recall.main(["--since", "2026-02-30"]) == 2


def test_short_date():
    assert recall.main(["--since", "2026-1-5"]) == 2


def test_api_bad_date():
    assert api.get_recall({"since": "nope"})["status"] == 400


def test_api_no_since():
    assert api.get_recall({})["memories"] == recall.MEMORIES


def test_order_kept():
    got = [m["id"] for m in recall.recall("2026-10-01")]
    assert got == sorted(got)
